const allowedCategories = new Set([
  "model-releases",
  "tools-repos",
  "breakthroughs",
  "opinion-insight"
]);

return items
  .filter(item => {
    const categories = item.json.category_details || [];

    // Require ALL category slugs to be in the allowed list
    return (
      categories.length > 0 &&
      categories.every(category => allowedCategories.has(category.slug))
    );
  })
  .map(item => ({
    json: {
      id: item.json.id,
      source: item.json.source_url,
      title: item.json.title,
      summary_extended: item.json.summary_extended,
      category_details: item.json.category_details.map(category => ({
        slug: category.slug
      }))
    }
  }));

// Removes duplicate stories BEFORE the Rate Limiter / AI curation step —
// the "Select Useful Stories" agent only ever sees one story at a time and
// has no way to spot duplicates itself, so this has to happen upstream of it.

// This node's single input is a MERGE of two sources (via "Merge Stories with
// History", Append mode): candidate stories from "Select Niche Stories"
// (shape: { id, title, ... }) and history rows from "Get Published Story
// History" (shape: { StoryID, Title, PublishedAt }). Separate them by shape
// below, since they arrive as one combined list.

function normalize(title) {
  return (title || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

const allItems = $input.all();
const historyRows = allItems.filter(item => item.json.StoryID !== undefined);
const candidates = allItems.filter(item => item.json.StoryID === undefined);

// Build the set of already-published stories from the history log.
const publishedIds = new Set();
const publishedTitles = new Set();

for (const row of historyRows) {
  const id = row.json.StoryID;
  const title = row.json.Title;

  if (id !== undefined && id !== null && id !== "") {
    publishedIds.add(String(id));
  }

  if (title) {
    publishedTitles.add(normalize(title));
  }
}

// Walk this week's candidate stories, dropping in-batch AND cross-week duplicates.
const seenIdsThisRun = new Set();
const seenTitlesThisRun = new Set();
const unique = [];

for (const item of candidates) {
  const story = item.json;
  const idKey =
    story.id !== undefined && story.id !== null
      ? String(story.id)
      : null;
  const titleKey = normalize(story.title);

  const isDuplicateInBatch =
    (idKey && seenIdsThisRun.has(idKey)) ||
    seenTitlesThisRun.has(titleKey);

  const isAlreadyPublished =
    (idKey && publishedIds.has(idKey)) ||
    publishedTitles.has(titleKey);

  if (isDuplicateInBatch || isAlreadyPublished) {
    continue; // skip: duplicate this week, or already covered in a past issue
  }

  if (idKey) seenIdsThisRun.add(idKey);
  seenTitlesThisRun.add(titleKey);
  unique.push(item);
}

// If nothing remains after duplicate removal, return a flag instead.
if (unique.length === 0) {
  return [
    {
      json: {
        new_stories: false,
      },
    },
  ];
}

// Add the flag to every remaining unique story.
return unique.map(item => ({
  json: {
    ...item.json,
    new_stories: true,
  },
}));

// The Useful Stories Picker (AI agent) is only trusted for its decision.
// The real story data is carried forward from the clean upstream source
// (Rate Limiter), matched by id, because the agent echoes nested fields
// (like category_details) unreliably.
const cleanItems = $('Rate Limiter').all().map(i => i.json);
const cleanById = {};
for (const c of cleanItems) { cleanById[c.id] = c; }

return $input.all().map((item, idx) => {
  const raw = item.json || {};
  const decision = raw.output ? raw.output : raw;
  const clean = cleanById[decision.id] || cleanItems[idx] || {};
  return {
    json: {
      id: clean.id,
      source: clean.source,
      title: clean.title,
      summary_extended: clean.summary_extended,
      category_details: clean.category_details,
      include_in_newsletter: decision.include_in_newsletter === true
    }
  };
});

// Runs exactly ONCE per execution — the newsletter content (subject + body)
// is generated a single time and is NOT regenerated or re-fetched per subscriber.
const { subject, body } = $('NewsLetter Humanizer').first().json.output;

let html = (body || "").trim();

// If the AI returned plain text instead of HTML, convert it into email-safe HTML.
const looksLikeHtml = /<(div|p|h1|h2|h3|hr|br|ul|ol|li|strong|em)\b/i.test(html);

if (!looksLikeHtml) {
  html = html
    .replace(/\r\n/g, "\n")
    .replace(/\n---\n/g, "<hr>")
    .replace(/\n\n+/g, "</p><p>")
    .replace(/\n/g, "<br>");

  html = `
<div style="font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:1.6;color:#222222;">
  <p>${html}</p>
</div>`;
}
// If the AI already returned HTML, it is left completely untouched here —
// the personalized greeting is inserted later, once per subscriber.

// A single shared newsletter object. Subscriber-specific personalization
// (the greeting) is applied downstream, after this is merged with the
// subscriber list — it is NOT applied here.
return [
  {
    json: {
      subject,
      html
    }
  }
];

// Runs once per subscriber item (n8n's native per-item execution model).
// Every subscriber gets their OWN greeting, inserted into their OWN copy
// of the shared newsletter HTML produced by "Format Newsletter HTML".
const firstName = $json.Name || "there";
let html = $json.html;

const greeting = `
<p>Hey ${firstName}, How's it going? 😊</p>
`;

// Insert the greeting immediately after the opening wrapper <div>.
// If there's no wrapper div, prepend the greeting instead.
if (/<div[^>]*>/i.test(html)) {
  html = html.replace(/(<div[^>]*>)/i, `$1${greeting}`);
} else {
  html = greeting + html;
}

return {
  json: {
    Name: $json.Name,
    Email: $json.Email,
    subject: $json.subject,
    html
  }
};
